const $=s=>document.querySelector(s);
const icons={discover:'<circle cx="12" cy="12" r="9"/><path d="m16 8-3 5-5 3 3-5z"/>',report:'<path d="M6 3h9l4 4v14H6zM14 3v5h5M9 12h7M9 16h5"/>',weekend:'<rect x="7" y="2" width="10" height="14" rx="5"/><path d="M4 11a8 8 0 0 0 16 0M12 19v3M8 22h8"/>',chat:'<path d="M21 11a9 8 0 0 1-9 8H7l-5 3 1-7a8 8 0 1 1 18-4zM7 10h10M7 14h6"/>',me:'<circle cx="12" cy="7" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>',back:'<path d="m14 5-7 7 7 7"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/>',pin:'<path d="M19 9c0 6-7 12-7 12S5 15 5 9a7 7 0 0 1 14 0z"/><circle cx="12" cy="9" r="2"/>',filter:'<path d="M3 6h18M3 12h18M3 18h18"/><circle cx="8" cy="6" r="2"/><circle cx="16" cy="12" r="2"/><circle cx="10" cy="18" r="2"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.discover}</svg>`;
const art=(type='sport')=>type==='gallery'?'<svg viewBox="0 0 180 110"><path d="M20 90h140M27 18h126v72H27zM38 28h42v46H38zM91 28h50v46H91zM38 65l13-18 9 10 9-23 11 31M91 63l12-15 12 7 14-20 12 28"/><circle cx="54" cy="38" r="4"/></svg>':type==='walk'?'<svg viewBox="0 0 180 110"><path d="M5 90h170M22 85V39M9 51l13-27 15 27zM130 85V30M114 45l16-31 17 31zM50 90c25-15 47-26 72-22M76 57l11-12 9 16M84 68l-8 21M92 69l10 20"/><circle cx="88" cy="35" r="6"/></svg>':'<svg viewBox="0 0 180 110"><ellipse cx="65" cy="38" rx="24" ry="31" transform="rotate(30 65 38)"/><path d="m49 64-23 34M45 30l35 20M48 19l40 23M40 43l33 19M61 8 44 59M73 13 55 68M85 23 68 65M121 64l13 14 19-19M121 64l-4-9 26-10 10 14M125 56l10 12M135 52l9 10M134 78l-4 12"/></svg>';
const state={page:'discover',mode:'八字',selected:'不限日主',liked:false,joined:false,accepted:false,openActivity:false,consent:false,topic:0,round:0,messages:[],wishes:['打一场轻松的羽毛球','看一个摄影展','沿河散步看日落','去滑雪，愿意带新手','一起逛书店','学一道彼此的拿手菜','听一场现场音乐','尝试一次陶艺','去公园拍照','来一场乒乓球']};
const notes={discover:['01','找人是主线','先明确想认识谁，再查看真实亮点。日主偏好由用户选择，八字不被包装成真实关系成功率。'],report:['02','认识自己，而非替你决定','报告解释日主与关系方向；自主找人与双向推荐分开。演示盘不用于真实择偶结论。'],profile:['05','让值得认识的地方被看见','动物分身、本人形象、经历和作品分别表达。约会清单是认识后的邀请入口。'],weekend:['03','先在线上，认真聊聊','周末预约3—5轮独立交流，每轮结束后私下选择。双向意愿才能进入后续私聊。'],chat:['06','同意了解，再逐步分享','话题不读取隐藏答案。解锁某个主题不等于公开全部资料，也不等于排他关系。'],activities:['04','活动服务于认识彼此','从已匹配对象的共同期待出发。两人邀约默认私密，开放同行需要双方明确同意。'],me:['07','公开范围由自己控制','匹配用途和展示权限分别设置。没有通过认证的资料，不显示已认证徽章。']};
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3300)}
function modal(html){$('#modal-content').innerHTML=html;$('#modal').showModal()}
function header(label='发现彼此'){return `<div class="topbar"><span class="wordmark">runae.</span><button class="location" data-action="city">${icon('pin')}北京 · 演示</button><button class="icon-btn" data-action="filters" aria-label="筛选">${icon('filter')}</button></div>`}
function nav(){const items=[['discover','发现'],['report','报告'],['weekend','线上聊'],['chat','消息'],['me','我的']];$('#nav').innerHTML=items.map(([p,t])=>`<button data-page="${p}" class="${state.page===p?'active':''}">${icon(p)}${t}</button>`).join('')}
function card(){return `<article class="profile-card"><button data-page="profile" style="display:block;padding:0;width:100%;text-align:left" aria-label="查看林予个人档案"><div class="portrait"><img src="assets/profile-placeholder.svg" alt="演示人物的半写实小狗耳朵头像"><span class="float">虚构档案 · 图像为AI创作</span><span class="portrait-bottom">比起自我介绍，想先一起做点事。</span></div></button><div class="card-body"><div class="name-row"><h3>林予 <small>32岁 · 北京</small></h3><span class="muted">约3—5公里 · 示例</span></div><div><span class="tag">丁火 · 演示</span><span class="tag">ENFP · 自述</span><span class="tag">天秤座 · 演示</span></div><p class="reason">你们都想认真恋爱、长期在北京发展，也都把羽毛球写进了约会清单。</p><p class="tiny">八字：火生土的传统关系；不代表现实适配结论。</p><div class="card-actions"><button class="btn secondary" data-page="profile">看TA的亮点</button><button class="btn" data-action="like">${state.liked?'已表达想认识':'想认识TA'}</button></div></div></article>`}
function discover(){return `<div class="page">${header()}<div class="eyebrow green">A LITTLE CLOSER TO YOU</div><h1 class="title" style="margin-top:12px">对的人，<br>也许就在附近。</h1><p class="subtitle">用你认同的方式相遇，再了解真实的彼此。</p><div class="tabs">${['八字','MBTI','星座'].map(t=>`<button data-mode="${t}" class="${state.mode===t?'active':''}">${t}找人</button>`).join('')}</div><div class="chips">${(state.mode==='八字'?['不限日主','指定日主','传统关系']:state.mode==='MBTI'?['不限类型','同类型','指定类型']:['不限星座','同星座','指定星座']).map((t,i)=>`<button class="chip ${i===0?'active':''}" data-action="${i===0?'resetFilter':'typeFilter'}">${i===0&&state.selected!=='不限日主'?state.selected:t}</button>`).join('')}</div><div class="banner"><span class="star">✳</span><h3>先听见，再遇见。</h3><p>周末3—5轮语音初识，把时间留给双方都想继续的人。</p><button data-page="weekend">看看周末安排　↗</button></div><div class="section-head"><h2>${state.selected==='不限日主'?'值得认识的人':state.selected+' · 寻找结果'}</h2><button class="text-btn" data-action="filters">双向条件</button></div>${state.selected==='不限日主'||state.selected==='丁火'?card():`<div class="white-card empty">演示资料中暂无符合「${state.selected}」的人。<br>真实产品应明确展示空结果，不忽略筛选条件。<br><button class="text-btn" data-action="resetFilter">清除偏好，看看演示档案 →</button></div>`}<p class="tiny">当前为交互原型，所有人物、关系标签、距离及推荐理由均为演示。</p></div>`}
function report(){return `<div class="page"><div class="topbar"><span>我的报告</span><span class="demo">演示报告</span></div><h1 class="title">认识自己，<br>也为相遇留点空间。</h1><div class="report-hero"><div class="eyebrow">YOUR ELEMENT / SAMPLE</div><div class="glyph">戊</div><h2>戊土日主</h2><p>日主是标签入口，完整八字需要综合解释。</p><div class="pillars">${[['年柱','辛未'],['月柱','丁酉'],['日柱','戊申'],['时柱','乙卯']].map(([a,b])=>`<div class="pillar"><small>${a}</small>${b[0]}<br>${b[1]}</div>`).join('')}</div></div><div class="white-card"><h3>我可以认识哪些日主？</h3><p>你可以自主选择想认识的人。下列是传统关系方向，不是“最佳伴侣名单”。</p><div class="relations"><button class="relation" data-pick="丁火"><b>丙 · 丁</b><small>火生土 · 生我</small></button><button class="relation" data-pick="癸水"><b>癸</b><small>戊癸合 · 天干合</small></button><button class="relation" data-pick="乙木"><b>甲 · 乙</b><small>木克土 · 克我</small></button></div><p class="tiny">点击关系可进入相应找人偏好。生、克、合不等于现实中的好坏。</p></div><div class="white-card"><h3>你想怎样找人？</h3><button class="btn full" data-action="typeFilter">我指定想认识的日主</button><button class="btn outline full" style="margin-top:9px" data-action="preferences">按双方现实期待推荐</button></div><button class="text-btn" data-action="birth">录入或更新我的出生信息 →</button><p class="tiny">此页为固定样例，未执行真实排盘。原始生辰不应出现在他人档案或分享链接中。</p></div>`}
function weekend(){return `<div class="page"><div class="topbar"><span>线上聊聊</span><span class="demo">自愿预约</span></div><h1 class="title">周末，先听听<br>彼此的声音。</h1><p class="subtitle">有明确恋爱意愿，也可以先轻松认识。</p><div class="weekend-hero"><div class="eyebrow">WEEKEND VOICE DATE</div><h2>不用赶场，<br>把初识留在线上。</h2><p>预约3—5轮独立语音交流。每轮10分钟，轮间留出休息时间。</p><div class="date"><span>本周六 19:00—20:00</span><span>计划示例</span></div></div><div class="steps"><div><b>01</b>确认期待与空闲</div><div><b>02</b>双方接受安排</div><div><b>03</b>聊完后私下互选</div></div><div class="white-card"><h3>每一次继续，都由你决定</h3><p>不群聊、不公开选择结果。只有双方都想继续，才开放私聊。报名不代表排他承诺。</p></div><button class="btn full" data-action="weekend">${state.joined?'查看我的体验安排':'选择时间 · 体验预约'}</button><div class="section-head"><h2>先试一轮，感受节奏</h2><span class="muted">不会接通真人</span></div><div class="white-card"><div class="list-row"><div class="mini-avatar"><img src="assets/profile-placeholder.svg" alt="林予的动物分身"></div><div class="row-text"><b>林予 · 演示对象</b><small>想认真恋爱 · 喜欢户外</small></div><button class="text-btn" data-action="voice">进入演示 →</button></div></div><p class="tiny">真实排期需有足够且双向同意的候选，不承诺每场凑满3—5人。当前没有真实报名或通话。</p></div>`}
function profile(){return `<div class="page"><div class="profile-cover"><img src="assets/profile-placeholder.svg" alt="演示人物林予的AI创作形象"><button class="icon-btn back-round" data-page="discover" aria-label="返回发现">${icon('back')}</button><span class="cover-caption">形象创作示例 · 不是真人核验照片</span></div><div class="profile-head"><h1>林予 <small style="font:13px sans-serif">32岁 · 北京</small></h1><p>医疗科技产品经理｜喜欢水上运动与摄影</p><span class="tag">丁火 · 演示</span><span class="tag">ENFP · 自述</span><span class="tag warm">认真恋爱</span></div><p class="reason">希望认识能一起探索世界，也能安心过日子的人。</p><div class="section-head"><h2>不止一张照片</h2><button class="text-btn" data-action="animal">看动物分身 ↗</button></div><div class="video">${art()}<button data-action="video" aria-label="打开运动视频示例">▶</button><span>我的周末 · 羽毛球与户外　00:38</span></div><div class="white-card" style="margin-top:15px"><h3>我想让你了解的三件事</h3><p>01　正在做一款医疗科技产品。<br>02　喜欢运动，羽毛球是休息方式之一。<br>03　希望长期在北京，也珍惜各自的独立空间。</p><p class="tiny" style="margin-top:9px">以上均为虚构示例。真实素材需本人确认后发布。</p></div><div class="section-head"><h2>想和你一起做的10件事</h2><span class="muted">match 后可邀请</span></div>${state.wishes.map((t,i)=>`<div class="wish"><span class="num">${String(i+1).padStart(2,'0')}</span><span class="wish-title">${t}</span><button data-wish="${i}">一起去 ↗</button></div>`).join('')}<div class="section-head"><h2>我与TA</h2></div><div class="white-card locked">${icon('lock')}<div><h3>更多了解，慢慢展开</h3><p>原始生日与私密问答不默认公开</p></div><button class="text-btn" data-action="unlock">邀请了解</button></div><button class="btn full" data-action="like">${state.liked?'前往双向意愿演示':'想认识TA'}</button></div>`}
const activitiesData=[{name:'羽毛球 · 双人轻松场',kind:'sport',label:'共同想做的事',place:'青禾运动馆 · 演示场地',time:'周六 15:00—16:00',route:'你约18分钟 · TA约22分钟',price:'80',unit:'／场 · 示例',detail:'室内场地1小时；球拍租赁另计。新手友好，轻松运动。',cost:'示例场地费80元／场；可商量AA各40元，实际费用以商家为准。'}, {name:'摄影展 · 慢慢逛一小时',kind:'gallery',label:'安静聊聊',place:'留白艺术空间 · 演示场地',time:'周六 14:00—18:00内入场',route:'你约25分钟 · TA约20分钟',price:'60',unit:'／人 · 示例',detail:'摄影展览；无需摄影基础。门票仅作演示，不代表真实售票。',cost:'示例票价60元／人，各自购票。'}, {name:'沿河散步 · 走到日落',kind:'walk',label:'免费也很美好',place:'城市滨河公园 · 演示地点',time:'周六 16:30—17:30',route:'你约15分钟 · TA约18分钟',price:'免费',unit:'公共空间',detail:'约3公里，轻松步行；提前查看天气，双方再确认集合地点。',cost:'活动本身免费，交通等个人支出自行安排。'}];
function activities(){return `<div class="page"><button class="back" data-page="chat">${icon('back')}返回与林予的聊天</button><div class="eyebrow green">A DATE, YOUR WAY</div><h1 class="title" style="margin-top:12px">把“有空一起”，<br>变成一个小计划。</h1><div class="partner"><div class="mini-avatar"><img src="assets/profile-placeholder.svg" alt="林予头像"></div><p>与林予一起 · 演示匹配<br><b>你们都想打羽毛球，也愿意散步看展。</b></p></div><div class="chips"><button class="chip active" data-action="activityFilter">双方路程合适</button><button class="chip" data-action="activityBudget">预算与时间</button><button class="chip" data-action="group">同行方式</button></div>${activitiesData.map((a,i)=>`<article class="activity"><div class="activity-art ${a.kind}">${art(a.kind)}<span class="category">${a.label}</span></div><div class="activity-body"><h3>${a.name}</h3><div class="activity-meta">${a.place}<br>${a.route}<br>${a.time}</div><div class="activity-price"><strong>${a.price==='免费'?'免费':'¥'+a.price}<small> ${a.unit}</small></strong><button class="btn" data-activity="${i}">商量这个计划</button></div></div></article>`).join('')}<p class="tiny">地点、路程、时段与价格均为演示，未使用定位或商家库存。真实活动需标注合作推广、包含项目与退改规则。此处不触发预约或付款。</p></div>`}
const topics=['你们都想打羽毛球：你更喜欢轻松来回，还是认真打一场？','如果周末有半天空闲，你最想和喜欢的人一起做什么？','各讲一件最近让自己开心的小事，为什么记到现在？'];
function chat(){return `<div class="page"><div class="chat-head"><button data-page="discover" aria-label="返回">${icon('back')}</button><div class="mini-avatar"><img src="assets/profile-placeholder.svg" alt="林予分身"></div><div><h2>林予</h2><p>双向意愿 · 聊天演示</p></div><button class="text-btn" style="margin-left:auto" data-page="profile">档案</button></div><div class="white-card locked">${icon('lock')}<div><h3>${state.accepted?'已授权：相处节奏':'了解彼此，按你的节奏'}</h3><p>${state.accepted?'仅展示本次双方同意的示例答案':'每组问题都需双方同意分享'}</p></div><button class="text-btn" data-action="unlock">${state.accepted?'查看':'邀请'}</button></div><div class="chat-time">今天 18:30 · 示例消息</div><div class="message">你好！看到你也喜欢羽毛球。比起坐着吃一顿饭，我更想一起轻松运动一下。</div><div class="message self">我也是。先聊聊，再挑一个我们都方便去的地方。</div>${state.messages.map(t=>`<div class="message self">${escapeHtml(t)}</div>`).join('')}<div class="topic"><div class="eyebrow">给你们的一张话题卡</div><h3>${topics[state.topic%topics.length]}</h3><div class="card-actions"><button class="btn secondary" data-action="newTopic">换个话题</button><button class="btn" data-action="sendTopic">聊这个</button></div></div><div class="white-card"><h3>下一次见面，做点什么？</h3><p>从共同清单出发，看双方都方便到达的场地、费用和时间。</p><button class="text-btn" data-page="activities">一起安排 →</button></div><div class="chips"><button class="chip" data-action="game">玩一轮默契二选一</button><button class="chip" data-action="voice">语音演示</button></div><form class="composer" id="message-form"><input name="message" maxlength="300" placeholder="写一句你想说的…" aria-label="聊天内容" required><button class="btn" type="submit">发送</button></form><p class="tiny" style="margin-top:8px">消息仅在本次原型内展示，不会发送给任何人。</p></div>`}
function me(){return `<div class="page"><div class="topbar"><span>我的</span><span class="demo">体验档案</span></div><div class="partner" style="padding:20px"><div class="mini-avatar" style="width:65px;height:65px"><img src="assets/profile-placeholder.svg" alt="动物头像"></div><div><h2 style="font:23px var(--serif);margin:0 0 8px">我的动物分身</h2><p>自己的亮点，值得被看见。</p></div></div><div class="section-head"><h2>完善我的表达</h2></div><div class="white-card">${[['上传生活素材','照片、作品、运动视频，整理真实亮点','upload'],['我的10件约会小事','先告诉对方：和我一起可以做什么','wishes'],['出生信息与报告','私密保存，展示范围单独控制','birth'],['认证中心','身份、学历等按项目核验','verification']].map(([a,b,c])=>`<div class="list-row"><div class="row-text"><b>${a}</b><small>${b}</small></div><button class="text-btn" data-action="${c}">管理 →</button></div>`).join('')}</div><div class="section-head"><h2>隐私由我决定</h2></div><div class="white-card"><label class="toggle-row">允许私密问答用于匹配<input type="checkbox" checked></label><label class="toggle-row">向所有人展示问答答案<input type="checkbox"></label><label class="toggle-row">公开自我介绍视频<input type="checkbox"></label><p class="tiny">开关为原型交互；真实服务必须分别落实授权、访问控制和删除机制。切换不会更改任何外部账户。</p></div><button class="btn outline full" data-action="preferences">我的找人条件</button></div>`}
function render(page=state.page){state.page=page;const views={discover,report,profile,weekend,chat,activities,me};$('#screen').innerHTML=(views[page]||discover)();$('#screen').scrollTop=0;nav();const n=notes[page]||notes.discover;$('#note-number').textContent=n[0];$('#note-title').textContent=n[1];$('#note-copy').textContent=n[2];document.querySelectorAll('.studio-links button').forEach(b=>b.style.color=b.dataset.page===page?'#b0714c':'');location.hash=page}
function escapeHtml(s){return s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function typeFilter(){modal(`<div class="eyebrow">你来选择探索方向</div><h2>想认识什么日主？</h2><p>指定日主是个人偏好，不代表相处结果。双方条件仍需彼此符合。</p><div class="chips">${['甲木','乙木','丙火','丁火','戊土','己土','庚金','辛金','壬水','癸水'].map(t=>`<button class="chip" data-pick="${t}">${t}</button>`).join('')}</div><div class="divider"></div><p>不知道选谁？可以不限定日主，先按双方的关系期待和现实条件探索。</p><button class="btn full" data-action="resetFilter">不限日主，先看看</button>`)}
function preferences(){modal(`<h2>先明确，你想认识谁</h2><form id="preferences-form"><label class="form-field">这次想建立的关系<select name="intent"><option>认真恋爱</option><option>普通朋友</option><option>先了解，再决定</option></select></label><label class="form-field">寻找范围<select name="distance"><option>同城，优先双方见面方便</option><option>附近约5公里</option><option>不限距离，愿意讨论异地</option></select></label><label class="form-field">婚育与定居期待<textarea name="expectation" style="display:block;width:100%;min-height:80px;border:1px solid #d6ddcf;border-radius:9px;padding:10px;margin-top:8px;font:inherit" placeholder="例如：希望长期在北京，婚育时间愿意一起商量"></textarea></label><p class="tiny">示例仅记录本次选择，不进行真实用户匹配。</p><button class="btn full" type="submit">确认本次偏好</button></form>`)}
function unlock(){if(state.accepted){modal(`<h2>相处节奏 · 已授权示例</h2><p>双方同意交换本主题的答案。其他问答仍未公开。</p><div class="comparison"><div>我希望怎样联系？<b>忙时可以少聊</b>希望提前说一声。</div><div>TA希望怎样联系？<b>每天有一次交流</b>不要求一直在线。</div></div><p>可以继续聊：很忙的那几天，怎样联系会让彼此安心？</p><button class="btn full" data-action="close">回到聊天</button>`);return}modal(`<h2>邀请一起了解<br>「相处节奏」</h2><p>本主题共3题。先独立回答，再由双方同意交换。邀请本身不公开任何答案。</p><div class="white-card"><p>我期待的联系频率？<br>忙碌时希望如何沟通？<br>意见不同时想怎样处理？</p></div><label class="check"><input type="checkbox" id="share-consent">我同意本主题答案仅向林予展示，其他信息保持原权限。</label><p class="tiny">下面仅模拟对方也已同意。真实产品必须等待对方独立确认。</p><button class="btn full" data-action="simulateUnlock">模拟双方同意并交换</button><p id="consent-error" class="error"></p>`)}
function plan(i){const a=activitiesData[i];modal(`<div class="eyebrow">两个人的小计划</div><h2>${a.name}</h2><p>${a.place}<br>${a.time}<br>${a.route}</p><div class="white-card"><h3>先说清楚，再轻松出发</h3><p>${a.detail}<br><br>${a.cost}</p></div><label class="form-field">想邀请的方式<select id="plan-mode"><option>两人邀约 · 默认私密</option><option>四人同行 · 待双方同意</option><option>开放小组 · 待双方同意</option></select></label><p class="tiny">当前为虚构场地，不可真实预订。选择开放模式也不会自动开放，须另获对方同意。</p><button class="btn full" data-send-plan="${i}">发送计划给TA · 演示</button>`)}
document.addEventListener('click',e=>{const el=e.target.closest('button,a');if(!el)return;if(el.dataset.page){render(el.dataset.page);return}if(el.dataset.mode){state.mode=el.dataset.mode;state.selected='不限日主';render();return}if(el.dataset.pick){state.selected=el.dataset.pick;$('#modal').close();render('discover');return}if(el.dataset.wish!==undefined){if(!state.liked){modal('<h2>先互相认识一下</h2><p>约会清单可以公开浏览，发起双人邀请需要先有双方的认识意愿。</p><button class="btn full" data-action="like">表达想认识 · 演示</button>')}else render('activities');return}if(el.dataset.activity!==undefined){plan(Number(el.dataset.activity));return}if(el.dataset.sendPlan!==undefined){const i=Number(el.dataset.sendPlan),mode=$('#plan-mode').value;state.messages.push(`想邀请你：${activitiesData[i].name}。方式：${mode}。时间、费用和是否参加，我们再一起确认。`);$('#modal').close();render('chat');toast('计划已加入演示聊天，等待对方确认；未真实预订。');return}if(el.dataset.gameChoice){const choice=el.dataset.gameChoice;$('#modal-content').innerHTML=`<h2>选择已揭晓</h2><div class="comparison"><div>你的选择<b>${choice}</b></div><div>TA的演示选择<b>提前计划</b></div></div><p>不同选择也有话题：你喜欢保留多少即兴空间？这不是关系评分。</p><button class="btn full" data-action="close">回到聊天</button>`;return}const action=el.dataset.action;if(!action)return;
switch(action){case'close':$('#modal').close();break;case'city':modal('<h2>寻找范围</h2><p>当前为北京的虚构演示，不获取你的真实位置。</p><button class="btn full" data-action="preferences">选择距离与关系期待</button>');break;case'filters':case'preferences':preferences();break;case'typeFilter':typeFilter();break;case'resetFilter':state.selected='不限日主';$('#modal').close();render('discover');break;case'like':state.liked=true;modal('<h2>你的兴趣，已表达。</h2><p>真实产品需等待对方独立选择。下面可以模拟双方都想继续，体验后续流程。</p><button class="btn full" data-action="simulateMatch">模拟双向意愿 →</button>');break;case'simulateMatch':$('#modal').close();render('chat');break;case'unlock':unlock();break;case'simulateUnlock':if(!$('#share-consent').checked){$('#consent-error').textContent='请先确认本主题的展示授权。';return}state.accepted=true;$('#modal').close();render('chat');break;case'newTopic':state.topic++;render('chat');break;case'sendTopic':state.messages.push(topics[state.topic%topics.length]);render('chat');break;case'weekend':modal(`<h2>${state.joined?'我的体验安排':'预约周末语音'}</h2><p>先确认空闲时间，再由双方接受具体安排。</p><form id="weekend-form"><label class="form-field">可参加时间<select><option>周六19:00—20:00</option><option>周日15:00—16:00</option></select></label><label class="form-field">希望交流几轮<select><option>3轮，每轮10分钟</option><option>4轮，每轮10分钟</option><option>5轮，每轮10分钟</option></select></label><p class="tiny">当前为交互演示，不会生成真实预约或保证候选人数。</p><button class="btn full" type="submit">保存体验安排</button></form>`);break;case'voice':state.round=0;modal('<h2>语音初识 · 演示</h2><p>本页没有麦克风接入，不会连接真人。</p><div class="white-card"><h3>给这一轮的开场</h3><p>如果周末有半天完全属于自己，你最想做什么？</p></div><button class="btn full" data-action="endVoice">结束体验，选择是否继续</button>');break;case'endVoice':modal('<h2>你愿意继续了解吗？</h2><p>真实场景中选择仅对本人可见，双方都愿意才建立联系。</p><button class="btn full" data-action="simulateMatch">愿意 · 模拟双方同意</button><button class="btn secondary full" style="margin-top:9px" data-action="declineVoice">暂不继续</button>');break;case'declineVoice':$('#modal').close();render('weekend');toast('已结束本轮演示，不向对方展示拒绝原因。');break;case'game':modal('<div class="eyebrow">轻松玩一轮</div><h2>猜猜TA的选择</h2><p>周末旅行，TA更喜欢哪种方式？只使用主动提供的演示内容。</p><button class="btn full" data-game-choice="提前计划">提前计划</button><button class="btn secondary full" style="margin-top:9px" data-game-choice="临时起意">临时起意</button>');break;case'animal':modal('<h2>我的小狗分身</h2><img src="assets/profile-placeholder.svg" alt="小狗表情包头像" style="width:100%;border-radius:17px"><p>创作形象可以有趣，真人核验与照片展示另行管理。</p>');break;case'video':modal('<h2>把真实亮点剪成短片</h2><p>这里是运动视频的位置示意，尚无真实视频。上传后可精选动作片段、添加本人确认的字幕；照片不能伪造成实际运动录像。</p><div class="activity-art">'+art()+'</div>');break;case'group':modal('<h2>两个人，或一起同行</h2><p>两人邀约默认私密。想邀请另一对或开放小组，必须先征得双方同意。参与活动不代表排他承诺。</p><button class="btn full" data-action="close">先和TA商量</button>');break;case'activityFilter':toast('真实推荐会比较双方出行时间；当前为示例路程。');break;case'activityBudget':modal('<h2>先确认彼此方便</h2><form id="budget-form"><label class="form-field">人均预算<select><option>免费—100元</option><option>100—300元</option><option>先商量，不限定</option></select></label><label class="form-field">可用时间<select><option>周六下午</option><option>周日上午</option><option>双方再协商</option></select></label><button class="btn full" type="submit">保存活动偏好</button></form>');break;case'birth':modal('<h2>认识自己，从这里开始</h2><form id="birth-form"><label class="form-field">历法<select><option>公历</option><option>农历</option></select></label><div class="form-grid"><label class="form-field">出生日期<input type="date" required></label><label class="form-field">时间，可留空<input type="time"></label></div><label class="form-field">出生城市<input placeholder="城市即可，不填具体地址" required></label><label class="check"><input type="checkbox" required>我了解本原型不计算真实命盘，提交后仅打开固定示例报告；所填内容不上传、不保存。</label><button class="btn full" type="submit">查看示例报告</button></form>');break;case'upload':modal('<h2>让你的亮点被看见</h2><p>从自己的运动、作品或生活照片开始。选取文件仅在本地预览，不会上传。</p><input id="material" type="file" accept="image/*,video/*" multiple style="max-width:100%"><div id="upload-preview" style="margin-top:15px"></div><p class="tiny">AI整理与视频生成尚未接入。所有文案和素材使用都需要本人确认。</p>');break;case'wishes':modal('<h2>我的约会小事</h2><p>先写一件也可以，不必为了填满而凑十件。</p><form id="wish-form"><label class="form-field">最想和对方一起做的事<input name="wish" required maxlength="45" placeholder="例如：一起去看摄影展"></label><button class="btn full" type="submit">保存到本次体验</button></form>');break;case'verification':modal('<h2>真实，比标签重要</h2><p>身份、学历、本人资产、家庭资产需分别核验，明确范围和日期。当前原型未接入认证，不能获得认证徽章。</p><div class="white-card"><p>身份核验　未接入<br>学历核验　未接入<br>资产核验　待定义核验范围</p></div>');break;}}
);
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target;if(f.id==='message-form'){const t=new FormData(f).get('message').trim();if(t){state.messages.push(t);render('chat');$('#screen').scrollTop=$('#screen').scrollHeight}return}if(f.id==='birth-form'){$('#modal').close();render('report');toast('已打开固定示例，未上传或保存出生信息。');return}if(f.id==='weekend-form'){state.joined=true;$('#modal').close();render('weekend');toast('体验安排已保存到本次页面；未真实报名。');return}if(f.id==='preferences-form'){$('#modal').close();toast('本次偏好已确认；尚未连接真实匹配服务。');return}if(f.id==='budget-form'){$('#modal').close();toast('活动偏好已确认；真实库存与筛选尚未接入。');return}if(f.id==='wish-form'){state.wishes[0]=new FormData(f).get('wish').trim();$('#modal').close();toast('已更新本次体验清单的第一项。');return}});
document.addEventListener('change',e=>{if(e.target.id==='material'){const files=[...e.target.files];const wrap=$('#upload-preview');wrap.replaceChildren();files.slice(0,6).forEach(file=>{const item=document.createElement(file.type.startsWith('video/')?'video':'img');item.src=URL.createObjectURL(file);item.style.cssText='width:100%;max-height:180px;object-fit:cover;border-radius:12px;margin-bottom:8px';if(item.tagName==='VIDEO')item.controls=true;else item.alt=file.name;wrap.appendChild(item)});const p=document.createElement('p');p.textContent=`已选择${files.length}个文件，预览前6个；未上传。`;wrap.appendChild(p)}});
$('#modal .close').addEventListener('click',()=>$('#modal').close());$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}});window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(notes[p]&&p!==state.page)render(p)});render(notes[location.hash.slice(1)]?location.hash.slice(1):'discover');
